// Conteúdo público de estudo. O gabarito da prova com código permanece no servidor.
export const characters=[{"id":"ada","icon":"👩🏾‍💻","name":"Ada","role":"Arquiteta da Web","description":"Organiza páginas claras e acessíveis."},{"id":"bia","icon":"👩🏻‍🎨","name":"Bia","role":"Designer de interfaces","description":"Transforma conteúdo em experiências úteis."},{"id":"leo","icon":"👨🏽‍🔬","name":"Léo","role":"Explorador de padrões","description":"Investiga como o navegador interpreta HTML."},{"id":"pixel","icon":"🤖","name":"Pixel","role":"Companheiro de missão","description":"Ajuda você a revisar cada decisão."}];
export const missions=[{"id":"estrutura","icon":"🏗️","world":"Fase 1 · Estrutura","title":"Primeira página","covers":[1,2,3,4,5],"intro":"HTML5 é o nome popular do HTML moderno, cuja especificação evolui continuamente. HTML organiza e dá significado ao conteúdo; CSS cuida da aparência, e JavaScript pode acrescentar comportamento. Comece pela anatomia de uma página.","concepts":[["HTML, elemento e tag","HTML usa elementos para marcar o papel de cada parte do conteúdo. Um elemento geralmente tem abertura, conteúdo e fechamento; a tag é a marca escrita entre sinais < e >.","Em <p>Olá!</p>, o elemento é o parágrafo inteiro; <p> e </p> são as tags.","<p>Olá, mundo!</p>"],["Atributos","Atributos acrescentam informações à tag de abertura. Escreva nome e valor entre aspas quando houver valor textual.","Em <html lang=\"pt-BR\">, lang informa o idioma principal.","<html lang=\"pt-BR\">"],["DOCTYPE","A declaração <!doctype html> fica antes de html e informa ao navegador que deve usar o modo padrão atual. Ela não é um elemento visual.","Coloque a declaração como primeira linha do arquivo.","<!doctype html>"],["Raiz <html>","O elemento html envolve o documento. Seu atributo lang ajuda leitores de tela, mecanismos de busca e ferramentas de tradução.","Uma página em português do Brasil usa lang=\"pt-BR\".","<html lang=\"pt-BR\">…</html>"],["<head> e metadados","head guarda informações sobre o documento, não o conteúdo principal exibido na página. Ali ficam codificação, título da aba e viewport.","A codificação UTF-8 permite representar caracteres como ç e ã.","<meta charset=\"utf-8\">"],["<title>","title dá nome ao documento na aba, nos favoritos e em outros contextos. Escreva um título específico para cada página.","Prefira 'Horários | Biblioteca' a 'Página 1'.","<title>Horários | Biblioteca</title>"],["<body>","body contém o que a pessoa vê e usa: textos, links, imagens, formulários e outras regiões.","O título visível da página deve ficar no body.","<body><h1>Minha página</h1></body>"],["Aninhamento e elementos vazios","Organize elementos como caixas dentro de caixas e feche os que precisam de fechamento. Alguns, como meta e img, não têm conteúdo interno nem tag final.","Um p termina antes do próximo bloco; img não usa </img>.","<p>Texto <strong>importante</strong>.</p>"],["Recursos externos <link> e <script>","link no head pode associar uma folha de estilos CSS. script pode carregar código JavaScript; defer permite executá-lo depois que a estrutura do documento for analisada. HTML, CSS e JavaScript têm funções diferentes.","Use um arquivo CSS para as cores e um script para interações.","<link rel=\"stylesheet\" href=\"estilos.css\"><script src=\"app.js\" defer></script>"]],"gate":{"q":"Onde fica o título mostrado na aba do navegador?","o":["No elemento <title> dentro de <head>","No atributo alt da imagem","No elemento <footer>","No atributo href"],"c":0,"why":"O elemento title define o título do documento na aba e em outros contextos."},"goal":"Reconhecer as partes de um documento e criar uma página válida do zero.","tags":["<!doctype html>","<html>","<head>","<meta>","<title>","<body>","<link>","<script>"],"lab":{"title":"Laboratório 1 · sua primeira página","sample":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Minha primeira página</title>\n</head>\n<body>\n  <h1>Olá, mundo!</h1>\n  <p>Estou aprendendo HTML.</p>\n</body>\n</html>","observe":"O título 'Minha primeira página' aparece na aba. 'Olá, mundo!' aparece no corpo da página.","task":"Crie um arquivo index.html, copie o exemplo e troque o título da aba e o h1 pelo nome de um projeto seu.","steps":["Salve o arquivo com extensão .html e codificação UTF-8.","Abra-o no navegador.","Compare o título da aba com o título visível e explique a diferença."],"solution":"<title>Portfólio de Ana</title>\n...\n<h1>Portfólio de Ana</h1>"}},{"id":"texto","icon":"✍️","world":"Fase 2 · Conteúdo","title":"Texto com significado","covers":[6,7,8,9,10],"intro":"Texto bem marcado é mais fácil de ler, navegar e reutilizar. Escolha a tag pelo sentido do conteúdo, não pelo tamanho ou pela cor que você deseja.","concepts":[["Títulos <h1> a <h6>","Os seis níveis de título organizam o assunto em partes. h1 indica o título principal; h2 abre uma seção; h3 subdivide essa seção.","Em uma página sobre cursos, 'Cursos' pode ser h1 e 'Turmas abertas' pode ser h2.","<h1>Cursos</h1><h2>Turmas abertas</h2>"],["Parágrafos <p>","p reúne uma ideia em um bloco de texto. Separe ideias diferentes em parágrafos próprios em vez de usar várias quebras de linha.","Um resumo do curso pode ficar em um p.","<p>Inscrições abertas até sexta-feira.</p>"],["Importância e ênfase","strong comunica importância forte; em altera a ênfase da frase. O navegador costuma mudar a aparência, mas o significado vem primeiro.","Use strong em um prazo decisivo e em em uma palavra que muda o tom da frase.","<p><strong>Atenção:</strong> prazo até sexta.</p>"],["Listas não ordenadas <ul>","ul agrupa itens cujo lugar na lista não altera o sentido. Cada item é um li.","Materiais necessários podem aparecer em qualquer ordem.","<ul><li>Caderno</li><li>Caneta</li></ul>"],["Listas ordenadas <ol>","ol representa etapas ou itens em sequência. Também usa li para cada item.","Passos de instalação devem preservar a ordem.","<ol><li>Baixe o arquivo</li><li>Abra no navegador</li></ol>"],["Quebra <br> e separação <hr>","br é uma quebra dentro do mesmo texto, útil em endereços ou versos. hr marca uma mudança de tema; nenhum substitui p ou CSS de espaçamento.","Para duas ideias diferentes, use dois parágrafos em vez de vários br.","<p>Rua Central, 10<br>São Paulo</p>"],["Código e citação","code identifica código; blockquote reúne uma citação em bloco. Essas tags ajudam a diferenciar exemplos técnicos e conteúdo citado.","Mostre uma tag dentro de code com os sinais escapados no arquivo HTML.","<p>Use <code>&lt;h1&gt;</code> para o título.</p>"]],"gate":{"q":"Uma receita exige passos em sequência. Qual estrutura é mais adequada?","o":["<ul>","<ol> com <li>","<div> sem marcação","<nav>"],"c":1,"why":"Uma lista ordenada preserva a sequência dos passos."},"goal":"Usar as tags básicas de texto para comunicar hierarquia, sequência e importância.","tags":["<h1>…<h6>","<p>","<strong>","<em>","<ul>","<ol>","<li>","<br>","<hr>","<code>"],"lab":{"title":"Laboratório 2 · página de curso","sample":"<h1>Curso de HTML5</h1>\n<p>Aprenda a criar páginas <strong>claras e acessíveis</strong>.</p>\n<h2>Materiais</h2>\n<ul>\n  <li>Computador</li>\n  <li>Navegador</li>\n</ul>\n<h2>Etapas</h2>\n<ol>\n  <li>Estude a estrutura</li>\n  <li>Crie uma página</li>\n</ol>","observe":"Há um título principal, duas seções, uma lista sem ordem obrigatória e uma sequência de etapas.","task":"Troque o tema do curso e acrescente um parágrafo, três materiais e três etapas. Explique por que uma lista usa ul e a outra usa ol.","steps":["Use apenas um h1 para o título principal deste exemplo.","Não use br para separar parágrafos.","Abra a página e confira a ordem das listas."],"solution":"<h1>Curso de Robótica</h1>\n<h2>Materiais</h2>\n<ul><li>Kit</li><li>Manual</li><li>Computador</li></ul>"}},{"id":"links","icon":"🔗","world":"Fase 3 · Navegação","title":"Caminhos pela Web","covers":[11,12,13,14,15],"intro":"Links conectam documentos e partes de uma página. O texto de cada link precisa dizer aonde ele leva, inclusive quando aparece isolado em uma lista.","concepts":[["Link <a href>","O elemento a se torna um link quando recebe href. O conteúdo entre as tags é o texto ou elemento acionável.","Uma página de contato pode ser ligada pelo arquivo contato.html.","<a href=\"contato.html\">Contato</a>"],["URL relativa","Um caminho relativo é calculado a partir da página atual. Use-o para navegar entre arquivos do mesmo projeto.","Em /aulas/index.html, ../imagens/logo.png aponta para a pasta imagens acima.","<a href=\"../index.html\">Início</a>"],["URL absoluta","Uma URL absoluta inclui protocolo e domínio. É adequada para outro site ou quando você precisa de um endereço completo.","Um link para a documentação externa começa com https://.","<a href=\"https://developer.mozilla.org/\">Documentação</a>"],["Âncora na mesma página","Um id identifica uma região; href com #id leva diretamente a ela. Cada id deve ser único no documento.","O índice pode apontar para a seção com id=\"exercicios\".","<a href=\"#exercicios\">Ir aos exercícios</a>"],["Texto descritivo","Escreva o destino ou a ação de forma específica. 'Clique aqui' perde o sentido fora do parágrafo.","'Consultar calendário escolar' informa mais que 'Saiba mais'.","<a href=\"calendario.html\">Consultar calendário escolar</a>"],["Navegação <nav>","nav delimita um conjunto importante de links de navegação, como o menu principal ou um índice de conteúdo.","Dê um nome ao nav quando houver mais de um menu.","<nav aria-label=\"Principal\">…</nav>"],["Nova guia com cuidado","target=\"_blank\" abre outra guia. Quando usá-lo, rel=\"noopener\" evita que a página aberta controle a guia de origem.","Nem todo link precisa abrir nova guia; preserve a expectativa de quem navega.","<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">Site externo</a>"]],"gate":{"q":"Qual texto ajuda a entender um link fora do contexto da página?","o":["Clique aqui","Saiba mais","Consultar horários da biblioteca","Abrir"],"c":2,"why":"O destino descrito no próprio link facilita navegação e acessibilidade."},"goal":"Criar navegação compreensível com links internos, relativos e externos.","tags":["<a>","href","id","<nav>","target","rel"],"lab":{"title":"Laboratório 3 · menu de estudo","sample":"<nav aria-label=\"Principal\">\n  <a href=\"#inicio\">Início</a>\n  <a href=\"#aulas\">Aulas</a>\n  <a href=\"contato.html\">Contato</a>\n</nav>\n<h1 id=\"inicio\">Portal de estudos</h1>\n<section id=\"aulas\">\n  <h2>Aulas disponíveis</h2>\n  <p>Escolha uma aula no menu.</p>\n</section>","observe":"Os links com # navegam nesta página; contato.html espera outro arquivo na mesma pasta.","task":"Adicione uma seção id=\"materiais\" e um link 'Ver materiais' no menu. Teste se a navegação chega à seção.","steps":["Não repita o mesmo id em dois elementos.","Use um texto de link que descreva o destino.","Clique no link e observe a mudança do endereço."],"solution":"<a href=\"#materiais\">Ver materiais</a>\n<section id=\"materiais\"><h2>Materiais</h2></section>"}},{"id":"midia","icon":"🖼️","world":"Fase 4 · Imagens e mídia","title":"Conteúdo visual acessível","covers":[16,17,18,19,20],"intro":"Mídia pode explicar melhor um assunto, desde que venha com alternativas e contexto. Pense no que a pessoa perderia se a imagem ou o som não estivesse disponível.","concepts":[["Imagem <img>","img insere uma imagem; src aponta para o arquivo. Informe dimensões quando conhecidas para reservar espaço e reduzir deslocamentos da página.","Uma foto de uma peça pode usar src=\"peca.jpg\".","<img src=\"peca.jpg\" alt=\"Engrenagem metálica\" width=\"400\" height=\"300\">"],["Texto alternativo alt","alt transmite a função ou o conteúdo relevante da imagem. Não precisa repetir 'imagem de', pois a tecnologia já identifica o elemento.","Para um gráfico, descreva a conclusão principal ou forneça explicação próxima.","<img src=\"grafico.png\" alt=\"Vendas cresceram de janeiro a março\">"],["Imagem decorativa","Quando uma imagem não acrescenta informação, use alt=\"\". Isso evita anúncio repetitivo ou inútil.","Um desenho de fundo que só enfeita o cartão pode ter alt vazio.","<img src=\"ornamento.svg\" alt=\"\">"],["Figura e legenda","figure agrupa conteúdo ilustrativo; figcaption fornece legenda visível relacionada à figura.","Uma foto de experimento pode trazer data e contexto na legenda.","<figure><img src=\"motor.jpg\" alt=\"Motor aberto\"><figcaption>Motor em inspeção.</figcaption></figure>"],["Imagem adaptativa <picture>","picture permite oferecer fontes diferentes para condições como largura de tela; img continua necessário como alternativa.","Uma versão vertical da foto pode servir melhor no celular.","<picture><source media=\"(max-width: 600px)\" srcset=\"foto-mobile.jpg\"><img src=\"foto.jpg\" alt=\"Equipe reunida\"></picture>"],["Áudio e vídeo","audio e video incorporam mídia. controls expõe controles nativos; forneça alternativas adequadas ao conteúdo.","Uma entrevista em áudio pode vir acompanhada de transcrição.","<audio controls src=\"entrevista.mp3\">Seu navegador não suporta áudio.</audio>"],["Legendas e quadros externos","track associa legendas temporizadas ao vídeo. Iframe incorpora outra página e deve receber um title que explique o conteúdo.","Um vídeo de aula pode ter legendas; um mapa incorporado deve ter nome acessível.","<track kind=\"captions\" src=\"legendas.vtt\" srclang=\"pt\" label=\"Português\">"]],"gate":{"q":"Qual atributo fornece alternativa textual para uma imagem informativa?","o":["src","alt","width","loading"],"c":1,"why":"alt transmite ao leitor o significado da imagem quando necessário."},"goal":"Inserir imagens, áudio e vídeo sem deixar informações importantes inacessíveis.","tags":["<img>","src","alt","<figure>","<figcaption>","<picture>","<audio>","<video>","<track>","<iframe>"],"lab":{"title":"Laboratório 4 · galeria acessível","sample":"<h1>Oficina de fotografia</h1>\n<figure>\n  <img src=\"foto.jpg\" alt=\"Alunos montando um robô\" width=\"480\" height=\"320\">\n  <figcaption>Equipe em atividade no laboratório.</figcaption>\n</figure>\n<p>Leia a legenda para entender o contexto.</p>","observe":"Se foto.jpg não existir, o texto alternativo ainda comunica a informação principal. A legenda contextualiza a figura.","task":"Substitua foto.jpg por uma imagem sua, reescreva alt com a informação essencial e crie uma legenda que acrescente contexto.","steps":["Não use o nome do arquivo como texto alternativo.","Se a imagem for só enfeite, use alt vazio.","Confira a página com a imagem desativada ou com caminho incorreto."],"solution":"<figure>\n  <img src=\"laboratorio.jpg\" alt=\"Dois alunos testando um circuito\" width=\"480\" height=\"320\">\n  <figcaption>Teste realizado durante a aula prática.</figcaption>\n</figure>"}},{"id":"semantica","icon":"🧭","world":"Fase 5 · Semântica","title":"Mapa da página","covers":[21,22,23,24,25],"intro":"Semântica é usar o elemento que expressa o papel do conteúdo. Isso ajuda navegação, manutenção e acessibilidade; aparência e cores continuam sendo trabalho do CSS.","concepts":[["Cabeçalho <header>","header introduz uma página ou seção. Pode conter título, logotipo e informações iniciais; não significa apenas uma faixa colorida.","O cabeçalho do site apresenta seu nome e o menu principal.","<header><h1>Portal da escola</h1></header>"],["Navegação <nav>","nav identifica uma área de links importantes. Não envolve qualquer link isolado da página.","Um índice de seções pode ter nav com nome acessível.","<nav aria-label=\"Índice\"><a href=\"#aulas\">Aulas</a></nav>"],["Conteúdo principal <main>","main contém o assunto central específico daquela página. Em geral, há um único main visível por documento.","Na página de uma disciplina, aulas e atividades ficam em main.","<main><h1>HTML5</h1><p>Bem-vindo.</p></main>"],["Seção <section>","section reúne um tema próprio e normalmente tem título. Não use section apenas como contêiner para criar margens.","Uma seção 'Perguntas frequentes' pode ter seu h2.","<section><h2>Perguntas frequentes</h2>…</section>"],["Artigo <article>","article é uma unidade que faz sentido sozinha, como notícia, postagem ou item de fórum.","Cada notícia do jornal escolar pode ser um article.","<article><h2>Feira de ciências</h2><p>…</p></article>"],["Complemento <aside>","aside reúne informação relacionada, mas secundária ao fluxo principal.","Um glossário ao lado da notícia pode ficar em aside.","<aside><h2>Glossário</h2><p>…</p></aside>"],["Rodapé <footer>","footer contém informações de fechamento da página ou seção, como autoria e contatos.","O rodapé do site pode trazer informações institucionais.","<footer><p>Escola Técnica · 2026</p></footer>"],["Contêineres e data","div e span não têm significado próprio; use-os quando nenhum elemento específico servir. time com datetime representa data ou hora legível por máquina.","Uma data de evento pode ser apresentada visualmente e codificada.","<time datetime=\"2026-10-07\">7 de outubro</time>"]],"gate":{"q":"Um texto de notícia que poderia ser publicado separadamente deve usar:","o":["<article>","<span>","<br>","<meta>"],"c":0,"why":"article representa uma composição independente."},"goal":"Descrever a função de cada região para que pessoas e navegadores compreendam a página.","tags":["<header>","<nav>","<main>","<section>","<article>","<aside>","<footer>","<div>","<span>","<time>"],"lab":{"title":"Laboratório 5 · notícia semântica","sample":"<header><h1>Jornal da escola</h1></header>\n<nav aria-label=\"Principal\"><a href=\"#noticias\">Notícias</a></nav>\n<main id=\"noticias\">\n  <article>\n    <h2>Feira de tecnologia</h2>\n    <p>As turmas apresentaram seus projetos.</p>\n  </article>\n  <aside><p>Próximo evento: mostra de robótica.</p></aside>\n</main>\n<footer><p>Escola Técnica</p></footer>","observe":"Cada região expressa seu papel: introdução, navegação, conteúdo central, notícia independente, complemento e fechamento.","task":"Acrescente uma segunda notícia como outro article e uma seção de agenda dentro de main. Dê títulos claros a cada parte.","steps":["Use article para cada notícia independente.","Dê um h2 à seção de agenda.","Confirme que o menu leva ao conteúdo com id correspondente."],"solution":"<section id=\"agenda\"><h2>Agenda</h2><p>Mostra de robótica: sexta-feira.</p></section>\n<article><h2>Nova biblioteca</h2><p>O espaço foi inaugurado.</p></article>"}},{"id":"tabelas","icon":"📊","world":"Fase 6 · Dados","title":"Tabelas que informam","covers":[26,27,28,29,30],"intro":"Tabelas servem para comparar dados. Uma tabela acessível informa qual cabeçalho descreve cada célula; ela não deve ser usada apenas para desenhar o layout da página.","concepts":[["Tabela <table>","table contém dados relacionados em linhas e colunas. Se os dados não têm essa relação, prefira outro elemento.","Uma relação de alunos, turmas e notas é tabular.","<table>…</table>"],["Legenda <caption>","caption nomeia e contextualiza a tabela. Ela faz parte da própria tabela e aparece antes das linhas no código.","'Notas do primeiro bimestre' explica o conjunto de dados.","<table><caption>Notas do bimestre</caption>…</table>"],["Linhas <tr>","tr representa uma linha. Dentro dela ficam células de cabeçalho th e células de dados td.","A linha de uma aluna contém nome e nota.","<tr><td>Ana</td><td>8,5</td></tr>"],["Cabeçalho <th> e scope","th indica o cabeçalho de uma coluna ou linha. scope=\"col\" e scope=\"row\" tornam a relação explícita.","'Aluno' pode ser cabeçalho de coluna; 'Ana' pode ser cabeçalho de sua linha.","<th scope=\"col\">Nota</th>"],["Célula de dados <td>","td guarda um valor comum. Não use th apenas para deixá-lo em negrito.","A nota 8,5 é um dado, então fica em td.","<td>8,5</td>"],["Grupos thead, tbody e tfoot","Esses elementos organizam cabeçalho, corpo e fechamento da tabela. São úteis em tabelas maiores.","O total de pontos pode ficar em tfoot.","<thead>…</thead><tbody>…</tbody><tfoot>…</tfoot>"],["Tabela não é layout","A disposição visual de cartões e colunas deve ser feita com CSS. Tabela é para dados que fazem sentido em linhas e colunas.","Um painel de cartões não precisa de table.","<div class=\"cards\">…</div>"]],"gate":{"q":"Em uma tabela de notas, qual célula representa o cabeçalho 'Aluno'?","o":["<td>","<th scope=\"col\">","<span>","<caption>"],"c":1,"why":"th identifica cabeçalho; scope col indica a coluna."},"goal":"Organizar dados em linhas e colunas com cabeçalhos que preservem as relações.","tags":["<table>","<caption>","<thead>","<tbody>","<tfoot>","<tr>","<th>","<td>","scope"],"lab":{"title":"Laboratório 6 · boletim simples","sample":"<table>\n  <caption>Notas da turma</caption>\n  <thead><tr><th scope=\"col\">Aluno</th><th scope=\"col\">Nota</th></tr></thead>\n  <tbody>\n    <tr><th scope=\"row\">Ana</th><td>8,5</td></tr>\n    <tr><th scope=\"row\">Bia</th><td>9,0</td></tr>\n  </tbody>\n</table>","observe":"Os títulos de coluna descrevem os dados; os nomes funcionam como títulos de linha.","task":"Adicione mais um aluno e uma coluna 'Situação'. Preencha as células e confira se cada linha tem a mesma estrutura.","steps":["Acrescente um th scope=\"col\" na primeira linha.","Acrescente um td correspondente em cada linha do corpo.","Mantenha caption para explicar a tabela."],"solution":"<th scope=\"col\">Situação</th>\n...\n<tr><th scope=\"row\">Carlos</th><td>7,0</td><td>Aprovado</td></tr>"}},{"id":"formularios","icon":"📝","world":"Fase 7 · Interação","title":"Formulários confiáveis","covers":[31,32,33,34,35],"intro":"Formulários recolhem respostas. A pessoa precisa saber o que preencher, e o servidor ainda deve verificar os dados recebidos: a validação do HTML melhora a experiência, mas não substitui a validação segura no servidor.","concepts":[["Formulário <form>","form reúne controles enviados juntos. action indica o destino; method indica como enviar, geralmente get ou post conforme a operação.","Uma inscrição enviada ao servidor pode usar method=\"post\".","<form action=\"/inscricao\" method=\"post\">…</form>"],["Rótulo <label>","label nomeia o campo. A associação explícita usa for no label e id igual no controle; clicar no rótulo ajuda a focar o campo.","'Nome completo' deve apontar para o input de nome.","<label for=\"nome\">Nome</label><input id=\"nome\" name=\"nome\">"],["Nome do dado <name>","O atributo name identifica o valor enviado pelo controle. id serve para referência no documento e associação ao rótulo; os dois têm funções diferentes.","Sem name, o valor do input pode não entrar nos dados submetidos.","<input id=\"email\" name=\"email\" type=\"email\">"],["Tipos de input","O atributo type escolhe o tipo de controle e pode oferecer teclado ou validação apropriados. Exemplos: email, number, date, checkbox e radio.","Um campo de e-mail deve usar type=\"email\", além de um label.","<input id=\"email\" name=\"email\" type=\"email\">"],["Validação nativa","required exige valor; minlength, maxlength, min e max definem limites conforme o tipo. Essas verificações acontecem no navegador e devem ser repetidas no servidor.","Um nome obrigatório pode ter required e minlength=\"3\".","<input name=\"nome\" required minlength=\"3\">"],["Texto longo e escolhas","textarea recebe texto em várias linhas. select reúne opções, cada uma em option; dê rótulos visíveis aos controles.","Uma mensagem pode usar textarea; a turma pode usar select.","<select id=\"turma\" name=\"turma\"><option value=\"a\">Turma A</option></select>"],["Grupo de campos","fieldset agrupa controles relacionados; legend dá um nome ao grupo. É útil para perguntas com várias alternativas.","Um conjunto de radios sobre turno pode ter legend 'Turno'.","<fieldset><legend>Turno</legend>…</fieldset>"],["Botão e envio","button type=\"submit\" envia o formulário; button type=\"button\" executa outra ação com script. Dizer o tipo evita envios acidentais.","Um botão 'Enviar inscrição' deve indicar submit.","<button type=\"submit\">Enviar inscrição</button>"]],"gate":{"q":"Como associar um rótulo visível a um campo?","o":["Mesmo valor em for do label e id do input","Mesmo texto em placeholder e value","Apenas cor igual","Mesmo nome de classe CSS"],"c":0,"why":"A associação explícita entre for e id melhora o uso do formulário."},"goal":"Criar formulários claros, rotulados e com validação inicial no navegador.","tags":["<form>","<label>","<input>","<textarea>","<select>","<option>","<fieldset>","<legend>","<button>","required"],"lab":{"title":"Laboratório 7 · inscrição acessível","sample":"<form action=\"/inscricao\" method=\"post\">\n  <label for=\"nome\">Nome completo</label>\n  <input id=\"nome\" name=\"nome\" required minlength=\"3\">\n  <label for=\"email\">E-mail</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <fieldset>\n    <legend>Turno</legend>\n    <label><input type=\"radio\" name=\"turno\" value=\"manha\"> Manhã</label>\n    <label><input type=\"radio\" name=\"turno\" value=\"tarde\"> Tarde</label>\n  </fieldset>\n  <button type=\"submit\">Enviar inscrição</button>\n</form>","observe":"Rótulos identificam campos; required e type=email ajudam na verificação inicial. Neste laboratório, o destino /inscricao é ilustrativo e não existe neste site.","task":"Acrescente um campo de mensagem opcional e um select de turma com duas opções. Não envie dados reais: o destino do exemplo é fictício.","steps":["Associe cada novo label ao id do controle.","Dê name aos campos que seriam enviados.","Teste a validação sem preencher os campos obrigatórios."],"solution":"<label for=\"mensagem\">Mensagem</label><textarea id=\"mensagem\" name=\"mensagem\"></textarea>\n<label for=\"turma\">Turma</label><select id=\"turma\" name=\"turma\"><option value=\"a\">Turma A</option><option value=\"b\">Turma B</option></select>"}},{"id":"avancado","icon":"🚀","world":"Fase 8 · Recursos avançados","title":"HTML moderno","covers":[36,37,38,39,40],"intro":"HTML moderno oferece recursos interativos e metadados úteis. Nem sempre é preciso criar tudo com JavaScript; escolha primeiro o elemento nativo adequado.","concepts":[["<details> e <summary>","details cria um bloco que pode abrir e fechar; summary fornece o título acionável. Funciona sem JavaScript.","Uma resposta de pergunta frequente pode ficar escondida até a pessoa abrir.","<details><summary>O que é HTML?</summary><p>É uma linguagem de marcação.</p></details>"],["<dialog>","dialog representa uma janela de diálogo. Um script pode abri-la com showModal(); o elemento open isolado exibe um diálogo não modal.","Uma confirmação exige foco e fechamento bem planejados.","<dialog open><p>Confirme a ação.</p></dialog>"],["<template>","template guarda marcação inerte que não aparece até ser copiada ou usada por script. É útil para componentes repetidos.","Um cartão de produto pode ser modelo para vários itens.","<template id=\"cartao\"><article><h2>Produto</h2></article></template>"],["<progress> e <meter>","progress mostra avanço de tarefa; meter mostra medida dentro de uma faixa conhecida. Não são intercambiáveis.","Use progress para 3 de 5 etapas e meter para uma avaliação de 8 em 10.","<progress value=\"3\" max=\"5\">3 de 5</progress>"],["<time>","time com datetime fornece uma data ou hora legível por máquina, mantendo uma forma amigável para a pessoa.","O evento pode mostrar '7 de outubro' e codificar 2026-10-07.","<time datetime=\"2026-10-07\">7 de outubro</time>"],["Imagem fora da tela","loading=\"lazy\" pode adiar imagens que ainda não estão próximas da área visível. Use com critério; imagem principal da página costuma precisar de carregamento imediato.","Uma foto no fim de um artigo pode ser carregada depois.","<img src=\"galeria.jpg\" alt=\"Alunos na mostra\" loading=\"lazy\">"],["<canvas> e conteúdo alternativo","canvas é uma área de desenho controlada por script. Conteúdo dentro do elemento serve como alternativa quando o desenho não pode ser usado; para dados importantes, ofereça equivalente acessível.","Um gráfico desenhado em canvas também pode ter tabela com os valores.","<canvas width=\"300\" height=\"150\">Gráfico: 10, 20 e 30.</canvas>"]],"gate":{"q":"Qual elemento guarda marcação inerte para ser usada mais tarde por código?","o":["<template>","<footer>","<main>","<strong>"],"c":0,"why":"O conteúdo de template não é renderizado diretamente até ser utilizado."},"goal":"Combinar recursos nativos modernos sem abrir mão de significado, acessibilidade e desempenho.","tags":["<details>","<summary>","<dialog>","<template>","<progress>","<meter>","<canvas>","<time>","loading"],"lab":{"title":"Laboratório 8 · painel de estudos","sample":"<h1>Painel de estudos</h1>\n<label for=\"progresso\">Missões concluídas</label>\n<progress id=\"progresso\" value=\"6\" max=\"8\">6 de 8</progress>\n<details>\n  <summary>Como revisar?</summary>\n  <p>Leia os exemplos e refaça os exercícios.</p>\n</details>\n<p>Próxima revisão: <time datetime=\"2026-10-07\">7 de outubro</time>.</p>","observe":"O resumo abre e fecha sem script; progress indica avanço; time representa a data de forma estruturada.","task":"Acrescente um segundo details com uma dica sobre formulários e atualize progress para representar 7 missões concluídas.","steps":["Use summary como primeiro filho de details.","Atualize value sem ultrapassar max.","Abra e feche a dica usando teclado e mouse."],"solution":"<progress value=\"7\" max=\"8\">7 de 8</progress>\n<details><summary>Dica de formulários</summary><p>Associe label e campo.</p></details>"}}];
export const practice=[{"covers":1,"text":"Qual linha inicial indica que o documento usa o padrão HTML moderno?","options":["<!doctype html>","<html5>","<meta html>","<standard>"],"correct":0,"explain":"DOCTYPE orienta o navegador a interpretar o documento no modo padrão.","mission":"estrutura"},{"covers":2,"text":"Em uma página em português do Brasil, qual abertura comunica corretamente o idioma?","options":["<body lang=\"br\">","<html lang=\"pt-BR\">","<head idioma=\"pt\">","<meta lang=\"portuguese\">"],"correct":1,"explain":"O atributo lang no elemento html informa o idioma principal.","mission":"estrutura"},{"covers":3,"text":"Onde inserir <meta charset=\"utf-8\">?","options":["No head","No footer","Dentro de cada p","No href"],"correct":0,"explain":"A codificação de caracteres é metadado do documento.","mission":"estrutura"},{"covers":4,"text":"Qual elemento contém o conteúdo visível principal da página?","options":["head","title","body","meta"],"correct":2,"explain":"body contém o conteúdo renderizado.","mission":"estrutura"},{"covers":5,"text":"Qual meta ajuda a adaptar a página a telas móveis?","options":["charset","viewport","author","refresh"],"correct":1,"explain":"A viewport orienta a área de visualização em dispositivos móveis.","mission":"estrutura"},{"covers":6,"text":"Qual título marca uma seção subordinada ao título principal?","options":["h2","h1","small","b"],"correct":0,"explain":"h2 representa o nível seguinte a h1 na hierarquia de títulos.","mission":"texto"},{"covers":7,"text":"Uma lista de equipamentos sem ordem de execução deve usar:","options":["ol","ul","nav","code"],"correct":1,"explain":"ul marca uma lista sem sequência obrigatória.","mission":"texto"},{"covers":8,"text":"Qual elemento marca um item dentro de ul?","options":["item","li","p","dt"],"correct":1,"explain":"li representa cada item de uma lista.","mission":"texto"},{"covers":9,"text":"Qual elemento comunica importância forte ao texto?","options":["b","span","strong","div"],"correct":2,"explain":"strong transmite importância sem depender apenas de estilo visual.","mission":"texto"},{"covers":10,"text":"Para exibir um pequeno trecho de código dentro de uma frase, use:","options":["code","main","aside","label"],"correct":0,"explain":"code marca código de computador dentro do conteúdo.","mission":"texto"},{"covers":11,"text":"Qual atributo define o destino de um link a?","options":["src","href","alt","type"],"correct":1,"explain":"href guarda o endereço de destino do link.","mission":"links"},{"covers":12,"text":"Um link para arquivo contato.html na mesma pasta pode usar:","options":["href=\"contato.html\"","src=\"contato.html\"","alt=\"contato.html\"","lang=\"contato.html\""],"correct":0,"explain":"Um caminho relativo localiza o arquivo a partir da página atual.","mission":"links"},{"covers":13,"text":"O que significa ../ em um caminho relativo?","options":["Pasta atual","Subir uma pasta","Ir para a raiz do domínio","Abrir nova guia"],"correct":1,"explain":"../ aponta para a pasta acima da atual.","mission":"links"},{"covers":14,"text":"Qual é o melhor texto de link para uma página de calendário escolar?","options":["Aqui","Ver","Calendário escolar","Clique"],"correct":2,"explain":"O link descritivo explica o destino por si.","mission":"links"},{"covers":15,"text":"Que elemento identifica uma região com links importantes de navegação?","options":["nav","footer","code","figure"],"correct":0,"explain":"nav marca uma seção de navegação principal ou relevante.","mission":"links"},{"covers":16,"text":"Para uma imagem que mostra um gráfico essencial, o alt deve:","options":["Ser sempre vazio","Descrever a informação importante","Repetir o nome do arquivo","Conter somente 'imagem'"],"correct":1,"explain":"A alternativa deve comunicar a função e o conteúdo relevantes.","mission":"midia"},{"covers":17,"text":"Uma imagem puramente ornamental deve ter:","options":["alt=\"\"","alt=\"decorativo decorativo\"","href=\"#\"","type=\"ornament\""],"correct":0,"explain":"Alt vazio impede leitura desnecessária por tecnologia assistiva.","mission":"midia"},{"covers":18,"text":"Como associar uma legenda a um diagrama?","options":["figure e figcaption","header e title","ul e li","form e input"],"correct":0,"explain":"figure agrupa o conteúdo; figcaption traz sua legenda.","mission":"midia"},{"covers":19,"text":"Que atributo mostra controles nativos em um vídeo?","options":["autoplay","controls","poster","width"],"correct":1,"explain":"controls disponibiliza controles de reprodução.","mission":"midia"},{"covers":20,"text":"Qual recurso HTML pode referenciar legendas de vídeo?","options":["track","canvas","aside","details"],"correct":0,"explain":"track permite faixas temporizadas, como legendas.","mission":"midia"},{"covers":21,"text":"Qual elemento contém o conteúdo principal único de uma página?","options":["main","div","nav","footer"],"correct":0,"explain":"main representa o conteúdo central do documento.","mission":"semantica"},{"covers":22,"text":"Uma notícia que faz sentido isoladamente pode ser marcada como:","options":["section","article","span","label"],"correct":1,"explain":"article representa conteúdo independente.","mission":"semantica"},{"covers":23,"text":"Uma barra lateral complementar ao artigo pode usar:","options":["aside","h1","meta","input"],"correct":0,"explain":"aside marca informação relacionada, mas secundária.","mission":"semantica"},{"covers":24,"text":"Qual elemento é genérico e não atribui significado semântico próprio?","options":["div","nav","main","article"],"correct":0,"explain":"div agrupa conteúdo quando não há elemento semântico mais específico.","mission":"semantica"},{"covers":25,"text":"Para uma seção temática com título, qual elemento é adequado?","options":["section","b","br","template"],"correct":0,"explain":"section representa agrupamento temático do documento.","mission":"semantica"},{"covers":26,"text":"Em tabela, qual elemento inicia uma linha?","options":["tr","td","th","caption"],"correct":0,"explain":"tr representa uma linha de tabela.","mission":"tabelas"},{"covers":27,"text":"Qual elemento descreve o tema da tabela?","options":["caption","title dentro de body","legend","summary"],"correct":0,"explain":"caption fornece legenda ou título da tabela.","mission":"tabelas"},{"covers":28,"text":"Qual atributo em th indica cabeçalho de linha?","options":["scope=\"row\"","type=\"row\"","role=\"data\"","for=\"row\""],"correct":0,"explain":"scope row relaciona o cabeçalho aos dados da linha.","mission":"tabelas"},{"covers":29,"text":"Qual célula é usada para dado comum?","options":["th","td","tr","table"],"correct":1,"explain":"td representa uma célula de dados.","mission":"tabelas"},{"covers":30,"text":"Tabelas devem ser usadas principalmente para:","options":["Montar toda a interface","Relacionar dados em linhas e colunas","Aplicar cores","Esconder conteúdo"],"correct":1,"explain":"Tabelas descrevem dados tabulares; o layout pertence ao CSS.","mission":"tabelas"},{"covers":31,"text":"Qual elemento reúne controles enviados pelo usuário?","options":["form","section","nav","figure"],"correct":0,"explain":"form define um formulário e seus controles associados.","mission":"formularios"},{"covers":32,"text":"Qual associação explícita liga o rótulo ao campo?","options":["for do label igual ao id do input","class igual ao placeholder","name igual ao title","alt igual ao value"],"correct":0,"explain":"for e id iguais vinculam o rótulo ao campo.","mission":"formularios"},{"covers":33,"text":"Qual tipo de input oferece validação básica de endereço eletrônico?","options":["type=\"text\"","type=\"email\"","type=\"url\"","type=\"tel\""],"correct":1,"explain":"email indica o tipo de dado e ativa verificações básicas do navegador.","mission":"formularios"},{"covers":34,"text":"Qual atributo exige o preenchimento de um campo antes do envio normal?","options":["mandatory","required","placeholder","patterned"],"correct":1,"explain":"required participa da validação nativa do formulário.","mission":"formularios"},{"covers":35,"text":"Qual par agrupa controles relacionados e nomeia o grupo?","options":["fieldset e legend","div e span","table e caption","video e track"],"correct":0,"explain":"fieldset agrupa; legend apresenta seu nome.","mission":"formularios"},{"covers":36,"text":"Qual elemento cria uma seção expansível nativa?","options":["details com summary","dialog com footer","main com aside","iframe com title"],"correct":0,"explain":"details e summary formam um controle expansível.","mission":"avancado"},{"covers":37,"text":"Que elemento representa uma janela de diálogo?","options":["dialog","menu","template","figure"],"correct":0,"explain":"dialog modela uma interação em janela.","mission":"avancado"},{"covers":38,"text":"O conteúdo de template é, inicialmente:","options":["Exibido automaticamente","Inerte e não renderizado","Enviado ao servidor","Um link externo"],"correct":1,"explain":"template guarda marcação para uso posterior.","mission":"avancado"},{"covers":39,"text":"Qual atributo pode adiar o carregamento de imagem fora da tela?","options":["loading=\"lazy\"","href=\"later\"","defer=\"image\"","alt=\"later\""],"correct":0,"explain":"loading lazy é uma dica de carregamento diferido.","mission":"avancado"},{"covers":40,"text":"Ao incorporar um iframe informativo, qual atributo descreve seu conteúdo para acessibilidade?","options":["title","srcset","width","loading"],"correct":0,"explain":"O title do iframe fornece um nome acessível para o conteúdo embutido.","mission":"avancado"}];
